pub fn squash(v: &mut Vec<String>) {
    let mut write = 0;
    for read in 0..v.len() {
        if write == 0 || v[write - 1] != v[read] {
            v[write] = v[read].clone();
            write += 1;
        }
    }
    v.truncate(write);
    for s in v.iter_mut() {
        *s = s.trim().to_string();
    }
}
