use std::collections::linked_list::LinkedList;
use std::collections::HashMap;
use std::hash::Hash;

pub struct Lru<K, V> {
    map: HashMap<K, usize>,
    list: LinkedList<(K, V)>,
    cap: usize,
}

impl<K: Eq + Hash, V> Lru<K, V> {
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "Lru cache capacity must be >= 1");
        Lru {
            map: HashMap::with_capacity(cap),
            list: LinkedList::new(),
            cap,
        }
    }

    pub fn put(&mut self, k: K, v: V) {
        if let Some(&idx) = self.map.get(&k) {
            self.list.set(idx, (k, v));
            self.list.move_front(idx);
            return;
        }
        if self.list.len() >= self.cap {
            let lru = self.list.pop_back().expect("cache not empty");
            self.map.remove(&lru.0);
        }
        let idx = self.list.push_front((k, v));
        self.map.insert(k, idx);
    }

    pub fn get(&mut self, k: &K) -> Option<&V> {
        let &idx = self.map.get(k)?;
        self.list.move_front(idx);
        self.list.get(idx).map(|entry| &entry.1)
    }
}
