use std::thread;

pub fn parallel_map<T, R, F>(mut items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();

    // Split `items` into exactly `workers` contiguous owned chunks.
    let mut chunks: Vec<Vec<T>> = Vec::with_capacity(workers);
    for w in 0..workers {
        let start = w * n / workers;
        let len = (w + 1) * n / workers - start;
        chunks.push(items.drain(..len).collect());
    }

    // One worker thread per chunk. Each spawned closure borrows `f` (safe
    // because `F: Sync`) and moves its chunk. Joining handles in chunk
    // order preserves the original input order.
    let mut out: Vec<R> = Vec::with_capacity(n);
    thread::scope(|s| {
        let mut handles = Vec::with_capacity(workers);
        for chunk in chunks {
            handles.push(s.spawn({
                let f = &f;
                move || chunk.into_iter().map(|x| f(x)).collect::<Vec<R>>()
            }));
        }
        for h in handles {
            out.extend(h.join().unwrap());
        }
    });

    out
}
