use std::marker::PhantomData;

/// An iterator over non-overlapping consecutive pairs of a slice,
/// yielding `(&mut T, &mut T)` for elements (0,1), (2,3), ....
/// An odd trailing element is never yielded.
pub struct PairsMut<'a, T> {
    ptr: *mut T,
    remaining: usize,
    _marker: PhantomData<(&'a mut T, &'a mut T)>,
}

/// Splits `s` into non-overlapping consecutive mutable pairs.
/// Does not use `chunks_mut`/`chunks_exact_mut`/`split_at_mut` —
/// aliasing safety is achieved via raw pointer arithmetic below.
pub fn pairs_mut<'a, T>(s: &'a mut [T]) -> PairsMut<'a, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        remaining: s.len(),
        _marker: PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.remaining < 2 {
            return None;
        }
        unsafe {
            // SAFETY:
            // - The only outstanding mutable borrow of the slice lives in
            //   `self` (created from the `&'a mut [T]` and never shared);
            //   `self.ptr` points inside the slice's allocation.
            // - Each call yields the two disjoint 1-element sub-ranges
            //   `[ptr, ptr+1)` and `[ptr+1, ptr+2)`, both of which are
            //   within the remaining (not-yet-issued) tail of the slice.
            // - We then advance `ptr` by 2 and shrink `remaining` by 2, so
            //   no element range is ever yielded twice and no aliasing
            //   between live `&mut`s can occur.
            let first = self.ptr;
            let second = self.ptr.add(1);
            self.ptr = self.ptr.add(2);
            self.remaining -= 2;
            Some((&mut *first, &mut *second))
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let pairs = self.remaining / 2;
        (pairs, Some(pairs))
    }
}
