use std::future::Future;
use std::pin::Pin;
use std::sync::{Arc, Condvar, Mutex};
use std::task::{Context, Poll, Wake};

/// Waker state backed by a condition variable plus a wake-token counter.
/// Every `wake`/`wake_by_ref` (even from another thread) increments the
/// counter under the mutex and notifies; every park consumes exactly one
/// token. This can never drop a wake (increments happen under the lock the
/// park holds), and it never re-polls without a wake token.
struct Notifier {
    guard: Mutex<u64>,
    notified: Condvar,
}

impl Wake for Notifier {
    fn wake(self: Arc<Self>) {
        let mut g = self.guard.lock().unwrap();
        *g += 1;
        self.notified.notify_one();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        let mut g = self.guard.lock().unwrap();
        *g += 1;
        self.notified.notify_one();
    }
}

/// Poll `fut` to completion on the current thread. When the future returns
/// `Pending`, the thread parks on a condition variable and is only re-polled
/// after the waker's `wake()` has been called — including when that call
/// comes from another thread after a delay.
pub fn block_on<F: Future>(fut: F) -> F::Output {
    let mut fut = Box::pin(fut);
    let notifier = Arc::new(Notifier {
        guard: Mutex::new(0),
        notified: Condvar::new(),
    });
    let waker = Arc::clone(&notifier).into();
    let mut cx = Context::from_waker(&waker);

    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(value) => return value,
            Poll::Pending => {
                loop {
                    let mut tokens = notifier.guard.lock().unwrap();
                    if *tokens > 0 {
                        *tokens -= 1;
                        break;
                    }
                    // Releases the lock and sleeps atomically; on wakeup the
                    // loop re-acquires and re-checks the token count.
                    drop(notifier.notified.wait(tokens).unwrap());
                }
            }
        }
    }
}

/// Yields control: each poll with `remaining > 0` decrements it, calls
/// `wake_by_ref` on the context's waker, and returns `Pending`; a poll with
/// `remaining == 0` resolves with `Ready(())`.
#[derive(Clone, Copy, Debug)]
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        if this.remaining > 0 {
            this.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}
